import{_ as a,o as t,c as d,aF as o}from"./chunks/framework.BYYyMsRq.js";const y=JSON.parse('{"title":"maplibre-layers","description":"Layer management for Kalisio map engine based on MapLibre","frontmatter":{"title":"maplibre-layers","description":"Layer management for Kalisio map engine based on MapLibre"},"headers":[],"relativePath":"packages/maplibre-layers/index.md","filePath":"packages/maplibre-layers/index.md"}'),r={name:"packages/maplibre-layers/index.md"};function i(s,e,c,n,l,p){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="maplibre-layers" tabindex="-1">maplibre-layers <a class="header-anchor" href="#maplibre-layers" aria-label="Permalink to &quot;maplibre-layers&quot;">​</a></h1><p><em>Layer management for Kalisio map engine based on MapLibre</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>maplibre-layers</code> turns a business <strong>layer definition</strong> (a plain JS object — id, type, url/data, style, filters, temporal config...) into the right combination of MapLibre GL JS sources/layers, Three.js objects, or deck.gl layers, and keeps it all in sync as the user changes the current time, toggles filters, or switches between 2D and 3D rendering.</p><p>It exposes a single class, <a href="#layermanager"><code>LayerManager</code></a>, orchestrated by <code>MapEngine</code> (<code>@kalisio/maplibre-core</code>) — nothing else in this package is meant to be imported directly by a host application. See <strong><a href="/maplibre-ekosystem/packages/maplibre-layers/architecture.html">Architecture</a></strong> for how <code>LayerManager</code> builds and wires up everything else internally (<code>Layer</code>, <code>LayerAdapter</code>, the per-engine adapters, <code>ThreeJsSceneManager</code>, <code>DeckGlManager</code>, the context objects, and the internal event bus) — this page covers the package&#39;s public surface and the layer definitions it accepts.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Install with your preferred package manager:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-FZdAd" id="tab-161ffSE" checked><label data-title="pnpm" for="tab-161ffSE">pnpm</label><input type="radio" name="group-FZdAd" id="tab-318cCNj"><label data-title="npm" for="tab-318cCNj">npm</label><input type="radio" name="group-FZdAd" id="tab-rRBiH1a"><label data-title="yarn" for="tab-rRBiH1a">yarn</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/maplibre-layers</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/maplibre-layers</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kalisio/maplibre-layers</span></span></code></pre></div></div></div><h2 id="public-exports" tabindex="-1">Public exports <a class="header-anchor" href="#public-exports" aria-label="Permalink to &quot;Public exports&quot;">​</a></h2><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { LayerManager, EngineContext, INTERNAL_EVENTS } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@kalisio/maplibre-layers&#39;</span></span></code></pre></div><ul><li><strong><code>LayerManager</code></strong> — instantiated once by <code>MapEngine</code>, with an <code>EngineContext</code>. Not meant to be constructed by a host application directly.</li><li><strong><code>EngineContext</code></strong> — the narrow, read-only view of engine state (<code>isRenderMode2D()</code>, <code>getTime()</code>, <code>getAppDefaultStyle()</code>) that <code>MapEngine</code> builds around its <code>StateManager</code> before handing it to <code>LayerManager</code>.</li><li><strong><code>INTERNAL_EVENTS</code></strong> — the names of the events exchanged over MapLibre&#39;s native event bus between engine subsystems (currently <code>RENDER_MODE_CHANGED</code> and <code>LAYER_DATA_UPDATED</code>). A host application should never need these — they&#39;re exported so <code>MapEngine</code> can emit <code>RENDER_MODE_CHANGED</code> without duplicating the string literal.</li></ul><p>Everything else — <code>Layer</code>, <code>LayerAdapter</code> and its subclasses, <code>LayerFactory</code>, <code>AdapterContext</code>, <code>ThreeJsSceneManager</code>, <code>DeckGlManager</code>, the providers, the temporal strategies — is an internal implementation detail.</p><h2 id="supported-layer-types" tabindex="-1">Supported layer types <a class="header-anchor" href="#supported-layer-types" aria-label="Permalink to &quot;Supported layer types&quot;">​</a></h2><p>Set via <code>definition.type</code> in the object passed to <code>MapEngine.addLayer()</code>.</p><table tabindex="0"><thead><tr><th><code>type</code></th><th>Renders via</th><th>Notes</th></tr></thead><tbody><tr><td><code>vector</code></td><td><code>VectorLayerAdapter</code> (2D) + <code>ThreeJsLayerAdapter</code> (3D)</td><td>GeoJSON sources. Supports per-filter styling and clustering (<code>definition.cluster</code>). If <code>definition.url</code> uses the <code>kazarr://</code> protocol, uses the N-dimensional variants instead (see below).</td></tr><tr><td><code>raster</code></td><td><code>MapLibreLayerAdapter</code> (2D only)</td><td>Standard raster tile source (<code>definition.tiles</code>).</td></tr><tr><td><code>raster-dem</code></td><td><code>MapLibreLayerAdapter</code> (2D only)</td><td>Hillshade rendering from a raster-dem source.</td></tr><tr><td><code>point-cloud</code></td><td><code>DeckGlLayerAdapter</code> (3D only)</td><td>Rendered as a deck.gl <code>Tile3DLayer</code> via the shared <code>DeckGlManager</code>.</td></tr><tr><td><code>mesh</code></td><td><code>DeckGlLayerAdapter</code> (3D only)</td><td>⚠️ Not implemented yet — <code>DeckGlLayerAdapter._createMeshLayer()</code> throws; wiring <code>@deck.gl/mesh-layers</code>&#39; <code>ScenegraphLayer</code> is still a TODO.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">wms is not currently routed</p><p><code>MapLibreLayerAdapter</code> has working WMS support (<code>_addWmsLayer()</code>), but <code>LayerFactory.createLayer()</code>&#39;s <code>switch</code> on <code>definition.type</code> has no <code>case &#39;wms&#39;</code> — a <code>{ type: &#39;wms&#39;, ... }</code> definition is silently given neither a 2D nor a 3D adapter today. This is a known gap, not a documented feature — flagged here rather than hidden.</p></div><h3 id="data-sources" tabindex="-1">Data sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data sources&quot;">​</a></h3><p>A layer definition can either embed <code>data</code> directly, or declare a <code>url</code>/<code>format</code> that resolves to a <strong>provider</strong>:</p><table tabindex="0"><thead><tr><th>Provider</th><th>Triggered by</th><th>Used for</th></tr></thead><tbody><tr><td><code>KazarrProvider</code></td><td><code>url</code> starting with <code>kazarr://</code></td><td>N-dimensional gridded data (Zarr) served by a Kazarr endpoint — supports spatial/temporal/level slicing, <code>variable(s)</code>, interpolation options.</td></tr><tr><td><code>KmlProvider</code></td><td><code>url</code> starting with <code>kml://</code>, or <code>format: &#39;kml&#39;</code></td><td>KML files, parsed to GeoJSON via <code>@loaders.gl/kml</code>.</td></tr></tbody></table><p>A <code>kazarr://</code> vector layer additionally gets <code>NDimensionalVectorLayerAdapter</code>/<code>NDimensionalThreeJsLayerAdapter</code>, which add <code>setLevel()</code>, <code>getVariables()</code>, <code>getCoordinates()</code>, <code>getCoordinate()</code> — surfaced on <code>MapEngine</code> as <code>setLayerLevel()</code>, <code>getVariables()</code>, <code>getCoordinates()</code>, <code>getCoordinate()</code>.</p><h3 id="temporal-updates" tabindex="-1">Temporal updates <a class="header-anchor" href="#temporal-updates" aria-label="Permalink to &quot;Temporal updates&quot;">​</a></h3><p>When <code>MapEngine.setTime()</code> targets a layer with a <code>definition.temporal</code> block, the layer picks a strategy based on its type (or <code>definition.temporalStrategy</code> if set explicitly):</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Used for</th><th>Mechanism</th></tr></thead><tbody><tr><td><code>filter</code></td><td><code>vector</code> (non-Kazarr)</td><td>Composes a MapLibre GL filter expression from the temporal window and re-applies it via <code>map.setFilter()</code> — no network request.</td></tr><tr><td><code>raster-url</code></td><td><code>raster</code>, <code>raster-dem</code>, <code>wms</code></td><td>Substitutes <code>{time}</code> in <code>definition.temporal.urlTemplate</code> and calls <code>source.setTiles()</code>; MapLibre cross-fades the tiles automatically.</td></tr><tr><td><code>set-data</code></td><td><code>point-cloud</code>, <code>mesh</code>, Kazarr-backed <code>vector</code></td><td>Reloads the layer&#39;s provider for the new instant and pushes the result via <code>source.setData()</code>.</td></tr></tbody></table><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p><code>definition.filters</code> declares named business sub-filters, each with an <code>id</code>, an <code>expression</code> (a MapLibre filter expression), and optionally a per-filter <code>style</code>. Toggle one at runtime with <code>MapEngine.setFilterActive(layerId, filterId, active)</code>.</p><h2 id="ordering" tabindex="-1">Ordering <a class="header-anchor" href="#ordering" aria-label="Permalink to &quot;Ordering&quot;">​</a></h2><p><code>LayerManager</code> also exposes layer z-ordering helpers used internally by the host application&#39;s layer list UI: <code>getLayersOrder(map)</code>, <code>moveLayerOnTop(map, layerId)</code>, <code>moveLayerOnBottom(map, layerId)</code>, <code>moveLayerOver(map, layerId, targetLayerId)</code>, <code>moveLayerUnder(map, layerId, targetLayerId)</code>.</p>',27)])])}const g=a(r,[["render",i]]);export{y as __pageData,g as default};
